import { ApiError } from '@lifepass/shared';

export type NotificationType =
  | 'new_institution_request'
  | 'consent_decision_needed'
  | 'consent_approved'
  | 'request_expired'
  | 'processing_completed'
  | 'record_status_change';

export interface NotificationItem {
  id: string;
  type: NotificationType;
  title: string;
  body: string;
  data?: {
    request_id?: string;
    record_id?: string;
    institution_name?: string;
    action_url?: string;
  };
  read_at: string | null;
  created_at: string;
}

