/**
 * Fixture resolver to retrieve notifications list.
 */
export async function getFixtureNotifications(): Promise<NotificationItem[]> {
  await new Promise((resolve) => setTimeout(resolve, 300));
  return mockNotifications.map((n) => ({ ...n }));
}

/**
 * Mark a single notification as read in fixture memory.
 */
export async function markFixtureNotificationRead(
  notificationId: string
): Promise<NotificationItem> {
  await new Promise((resolve) => setTimeout(resolve, 150));

  const index = mockNotifications.findIndex((n) => n.id === notificationId);
  if (index === -1) {
    const error: ApiError = {
      code: 'NOT_FOUND',
      message: `Notification "${notificationId}" not found.`,
    };
    throw error;
  }

  mockNotifications[index] = {
    ...mockNotifications[index],
    read_at: new Date().toISOString(),
  };

  return { ...mockNotifications[index] };
}

/**
 * Mark all notifications as read in fixture memory.
 */
export async function markAllFixtureNotificationsRead(): Promise<NotificationItem[]> {
  await new Promise((resolve) => setTimeout(resolve, 200));

  const now = new Date().toISOString();
  mockNotifications = mockNotifications.map((n) => ({
    ...n,
    read_at: n.read_at || now,
  }));

  return mockNotifications.map((n) => ({ ...n }));
}
